namespace App\Modules\Contracts\Admin;

use App\Modules\Contracts\Application\ContractService;
use App\Modules\Contracts\Domain\Contract;
use App\Modules\Contracts\Domain\ContractStatus;
use App\Platform\Identity\Domain\Identity;
use App\Platform\Identity\Domain\User;
use App\Platform\Storage\ObjectStorage;
use App\Shared\Domain\Exception\ConflictException;
use App\Shared\Domain\Exception\NotFoundException;
use App\Shared\Domain\Exception\ValidationException;
use App\Shared\Infrastructure\Http\Responder;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Yiisoft\Router\CurrentRoute;
use Yiisoft\User\CurrentUser;

/**
 * Admin · Contracts: list with search/filters/sort/paging (HTMX), create/edit with validation errors (422),
 * detail with activity timeline, lifecycle transitions, delete (confirm) and the background CSV report. All rules live in ContractService.
 */
final class ContractsController
{
    public const PER_PAGE = 20;
    public const FILTERS = ['status', 'owner_id'];
    public const INPUT = ['title', 'amount', 'due_on', 'owner_id'];

    public function __construct(
        private readonly Responder $responder,
        private readonly ContractService $service,
        private readonly CurrentUser $currentUser,
        private readonly CurrentRoute $route,
        private readonly ObjectStorage $storage,
    ) {}

    public function index(ServerRequestInterface $request): ResponseInterface
    {
        $actor = $this->actor();
        $params = $request->getQueryParams();
        $filters = ['q' => self::str($params, 'q')];
        foreach (self::FILTERS as $k) {
            $filters[$k] = self::str($params, $k);
        }
        $page = $this->service->search($actor, $filters, max(1, (int) ($params['page'] ?? 1)), self::PER_PAGE, self::str($params, 'sort') ?: null);
        return $this->responder->render('@modules/Contracts/Admin/views/index', [
            'page' => $page,
            'filters' => $filters,
            'query' => array_filter($filters + ['sort' => self::str($params, 'sort')], static fn($v) => $v !== ''),
            'counts' => $this->service->countsByStatus($actor),
            'reports' => $this->service->recentReports($actor),
        ]);
    }

    public function createForm(): ResponseInterface
    {
        return $this->form(null, [], []);
    }

    public function store(ServerRequestInterface $request): ResponseInterface
    {
        $input = $this->input($request);
        try {
            $e = $this->service->create($this->actor(), $input);
        } catch (ValidationException $ex) {
            return $this->form(null, $input, $ex->errors(), 422);
        }
        $this->responder->success('Contract created.');
        return $this->responder->redirect('admin.contracts.view', ['id' => $e->id]);
    }

    public function view(): ResponseInterface
    {
        $actor = $this->actor();
        $e = $this->service->get($actor, $this->id());
        return $this->responder->render('@modules/Contracts/Admin/views/view', [
            'entity' => $e,
            'activity' => $this->service->activity($actor, $e->id),
            'transitions' => $e->status()->allowedTransitions(),
        ]);
    }

    public function editForm(): ResponseInterface
    {
        $e = $this->service->get($this->actor(), $this->id());
        return $this->form($e, self::formValues($e), []);
    }

    public function update(ServerRequestInterface $request): ResponseInterface
    {
        $actor = $this->actor();
        $input = $this->input($request);
        $version = (int) (((array) $request->getParsedBody())['version'] ?? 0);
        try {
            $e = $this->service->update($actor, $this->id(), $input, $version);
        } catch (ValidationException $ex) {
            return $this->form($this->service->get($actor, $this->id()), $input + ['version' => $version], $ex->errors(), 422);
        } catch (ConflictException $ex) {
            $this->responder->error($ex->getMessage());
            return $this->responder->redirect('admin.contracts.edit', ['id' => $this->id()]);
        }
        $this->responder->success('Contract saved.');
        return $this->responder->redirect('admin.contracts.view', ['id' => $e->id]);
    }

    public function status(ServerRequestInterface $request): ResponseInterface
    {
        $body = (array) $request->getParsedBody();
        try {
            $e = $this->service->changeStatus($this->actor(), $this->id(), (string) ($body['status'] ?? ''),
                isset($body['version']) ? (int) $body['version'] : null, trim((string) ($body['comment'] ?? '')));
            $this->responder->success('Status changed to ' . $e->status()->label() . '.');
        } catch (ConflictException | ValidationException $ex) {
            $this->responder->error($ex->getMessage());
        }
        return $this->responder->redirect('admin.contracts.view', ['id' => $this->id()]);
    }
    public function delete(ServerRequestInterface $request): ResponseInterface
    {
        $body = (array) $request->getParsedBody();
        try {
            $this->service->delete($this->actor(), $this->id(), isset($body['version']) ? (int) $body['version'] : null);
        } catch (ConflictException $ex) {
            $this->responder->error($ex->getMessage());
            return $this->responder->redirect('admin.contracts.view', ['id' => $this->id()]);
        }
        $this->responder->success('Contract deleted.');
        return $this->responder->redirect('admin.contracts');
    }

    public function requestReport(ServerRequestInterface $request): ResponseInterface
    {
        $body = (array) $request->getParsedBody();
        $filters = [];
        foreach (['q', ...self::FILTERS] as $k) {
            if (self::str($body, $k) !== '') {
                $filters[$k] = self::str($body, $k);
            }
        }
        $r = $this->service->requestReport($this->actor(), $filters);
        $this->responder->success('Report generation queued.');
        return $this->responder->redirect('admin.contracts.report', ['id' => $r['report_id']]);
    }

    public function report(): ResponseInterface
    {
        return $this->responder->render('@modules/Contracts/Admin/views/report', [
            'report' => $this->service->report($this->actor(), $this->id()),
            'storageConfigured' => $this->storage->isConfigured(),
        ]);
    }

    public function download(): ResponseInterface
    {
        $report = $this->service->report($this->actor(), $this->id());
        if ($report['status'] !== 'done' || $report['path'] === null) {
            throw new NotFoundException('The report is not ready.');
        }
        $csv = $this->storage->filesystem()->read((string) $report['path']);
        return $this->responder->download($csv, 'contracts-report-' . substr((string) $report['id'], 0, 8) . '.csv', 'text/csv; charset=utf-8');
    }
    // ------------------------------------------------------------------ helpers

    private function form(?Contract $entity, array $values, array $errors, int $status = 200): ResponseInterface
    {
        return $this->responder->render('@modules/Contracts/Admin/views/form', [
            'entity' => $entity,
            'values' => $values,
            'errors' => $errors,
        ], status: $status);
    }

    /** @return array<string,mixed> form values of an existing record */
    public static function formValues(Contract $e): array
    {
        return [
            'title' => ($e->title() ?? ''),
            'amount' => ($e->amount() ?? ''),
            'due_on' => ($e->dueOn() ?? ''),
            'owner_id' => ($e->ownerId() ?? ''),
            'version' => $e->version(),
        ];
    }

    /** @return array<string,string> editable attributes from the POST body (strings only) */
    private function input(ServerRequestInterface $request): array
    {
        $body = (array) $request->getParsedBody();
        $in = [];
        foreach (self::INPUT as $k) {
            if (array_key_exists($k, $body) && is_string($body[$k])) {
                $in[$k] = $body[$k];
            }
        }
        return $in;
    }

    private function actor(): User
    {
        $identity = $this->currentUser->getIdentity();
        if (!$identity instanceof Identity) {
            throw new NotFoundException();
        }
        return $identity->user;
    }

    private function id(): string
    {
        return (string) $this->route->getArgument('id');
    }

    private static function str(array $a, string $k): string
    {
        return isset($a[$k]) && is_scalar($a[$k]) ? trim((string) $a[$k]) : '';
    }
}
